export type AsExportName = keyof AsExports;

/** Every global the AssemblyScript module exports; read with `.value`. */
export interface AsGlobals {
    /** `i32` */
    MAX_COLLISION_OBJECTS: WebAssembly.Global;
    /** `i32` */
    MEMORY_LAYOUT_END: WebAssembly.Global;
    /** `i32` */
    JOINT_FIXED: WebAssembly.Global;
    /** `i32` */
    JOINT_HINGE: WebAssembly.Global;
    /** `i32` */
    JOINT_SPRING: WebAssembly.Global;
}

/**
 * Structs JS writes into native memory and passes by pointer
 * (scripts/native-structs.json). Pass one to defineNativeStruct()
 * (src/utils/native-memory.ts); every field is 4 bytes, in this order.
 */
export const NATIVE_STRUCTS = {
    /** One collision object in the BATCH_UPLOAD region. type and flags are stored as f32 and cast to i32 on read. Read by assembly/physics.ts addCollisionObjectsBatch. */
    CollisionObject: {
        type: 'f32',
        x: 'f32',
        y: 'f32',
        z: 'f32',
        d1: 'f32',
        d2: 'f32',
        d3: 'f32',
        flags: 'f32',
    },
} as const;
